// Normalize PubMed, bioRxiv, patent, and clinical-trial results into one
// document shape, then dedupe against documents already seen in prior runs.
const cfg = $('Set - Config').first().json;
const merged = $input.first().json;

const pubmedData = merged.pubmed || merged[0] || {};
const biorxivData = merged.biorxiv || merged[1] || {};
const patentsData = merged.patents || merged[2] || {};
const trialsData = merged.trials || merged[3] || {};

function simpleHash(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16);
}

const docs = [];

const pmids = pubmedData.esearchresult?.idlist || [];
for (const id of pmids) {
  docs.push({
    sourceType: 'journal_article',
    docId: 'pubmed:' + id,
    title: 'PubMed article ' + id,
    abstractOrClaims: '',
    url: 'https://pubmed.ncbi.nlm.nih.gov/' + id + '/',
    publishedDate: null,
    orgOrAuthors: null
  });
}

const preprints = biorxivData.collection || (Array.isArray(biorxivData) ? biorxivData : []);
for (const p of preprints) {
  docs.push({
    sourceType: 'preprint',
    docId: 'biorxiv:' + (p.doi || p.title),
    title: p.title || 'Untitled preprint',
    abstractOrClaims: p.abstract || '',
    url: p.doi ? ('https://doi.org/' + p.doi) : null,
    publishedDate: p.date || null,
    orgOrAuthors: p.authors || null
  });
}

const patents = patentsData.patents || (Array.isArray(patentsData) ? patentsData : []);
for (const p of patents) {
  docs.push({
    sourceType: 'patent',
    docId: 'patent:' + (p.patent_number || p.patent_id || p.patent_title),
    title: p.patent_title || 'Untitled patent',
    abstractOrClaims: p.patent_abstract || p.patent_claims || '',
    url: p.patent_number ? ('https://patents.google.com/patent/' + p.patent_number) : null,
    publishedDate: p.patent_date || null,
    orgOrAuthors: p.assignees || null
  });
}

const trials = trialsData.studies || (Array.isArray(trialsData) ? trialsData : []);
for (const t of trials) {
  const nctId = t.protocolSection?.identificationModule?.nctId || t.nctId;
  docs.push({
    sourceType: 'clinical_trial',
    docId: 'trial:' + nctId,
    title: t.protocolSection?.identificationModule?.briefTitle || 'Untitled trial',
    abstractOrClaims: t.protocolSection?.descriptionModule?.briefSummary || '',
    url: nctId ? ('https://clinicaltrials.gov/study/' + nctId) : null,
    publishedDate: t.protocolSection?.statusModule?.lastUpdatePostDateStruct?.date || null,
    orgOrAuthors: t.protocolSection?.sponsorCollaboratorsModule?.leadSponsor?.name || null
  });
}

// Dedupe across runs using workflow static data
const staticData = $getWorkflowStaticData('node');
if (!staticData.seenDocs) staticData.seenDocs = {};

const newDocs = [];
for (const d of docs) {
  const key = simpleHash(d.docId);
  if (!staticData.seenDocs[key]) {
    staticData.seenDocs[key] = { firstSeen: new Date().toISOString() };
    newDocs.push({ ...d, dedupeKey: key, watchTargets: cfg.watchTargets, noveltyThreshold: cfg.noveltyThreshold, pineconeIndexUrl: cfg.pineconeIndexUrl, pineconeNamespace: cfg.pineconeNamespace, airtableBaseId: cfg.airtableBaseId, airtableTableId: cfg.airtableTableId, slackChannel: cfg.slackChannel });
  }
}

if (newDocs.length === 0) {
  return [{ json: { noNewDocuments: true, totalCandidates: docs.length } }];
}

return newDocs.map(d => ({ json: d }));

const aiResponse = $input.first().json;
const doc = $('Split In Batches - Process Documents One at a Time').first().json;

let extraction;
try {
  const rawText = aiResponse.content?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  extraction = JSON.parse(cleaned);
} catch (e) {
  extraction = { drugTargets: [], molecules: [], mechanismOfAction: '', indication: '', developmentStage: '', competingOrganizations: [], isFirstInClass: false, noveltyNotes: 'Extraction failed to parse', summary: '' };
}

return [{
  json: {
    ...doc,
    ...extraction
  }
}];

const item = $input.first().json;

const watchList = (item.watchTargets || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const matchedTargets = (item.drugTargets || []).filter(t => watchList.includes((t || '').toLowerCase()));

let score = 0;
score += matchedTargets.length * 20;
score += item.isFirstInClass ? 30;
score += (item.molecules || []).length > 0 ? 10 : 0;
score += (item.competingOrganizations || []).length > 0 ? 10 : 0;
score = Math.min(100, score);

const highValue = score >= (item.noveltyThreshold ?? 75) || item.isFirstInClass;

return [{
  json: {
    ...item,
    matchedWatchTargets: matchedTargets,
    relevanceScore: score,
    highValue
  }
}];

const items = $input.all();
const staticData = $getWorkflowStaticData('node');
const totalSeen = Object.keys(staticData.seenDocs || {}).length;

return [{
  json: {
    runCompletedAt: new Date().toISOString(),
    totalDocumentsIndexedAllTime: totalSeen,
    digestNote: 'Run complete. See Airtable and Pinecone for the full indexed set; high-value discoveries this run were already alerted individually to Slack.'
  }
}];
